from pathlib import Path
import html,json,re,shutil
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E42')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
assert 'VÉRITÉ OK' in (D/'research-gate.log').read_text()
ledger=json.loads((D/'source-ledger.json').read_text())['sources'];pops=[];summaries=[]
def w(k,label):return f'<button class="w" data-k="e42-{k}">{label}</button>'
def table(h,rows):return '<table class="t" data-e42-table="1"><thead><tr>'+''.join('<th>'+x+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def pop(k,title,body):pops.append(f'<template data-pop="e42-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
def sec(k,title,body,summary):
 a='e42-'+str(k);pk='pareto-'+a;summaries.append(f'<template data-pop="{pk}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary}</p><p class="ratio" data-cover="{a}"></p></template>')
 return f'<section class="ilot" id="{a}"><h2><span class="n">{k}</span>{title}</h2>{body}<div class="key"><b>À retenir.</b> {summary}</div><button class="pareto-btn ui" data-k="{pk}">Essentiel de cette partie</button></section>'
def logical(a,b,c,caption):
 t='<figure><svg role="img" viewBox="0 0 450 246" aria-label="Schéma logique sans anatomie générée">'
 for i,label in enumerate([a,b,c]):
  y=5+80*i;t+=f'<rect x="8" y="{y}" width="434" height="54" rx="8" fill="none" stroke="currentColor"/><text x="225" y="{y+33}" font-size="17" fill="currentColor" text-anchor="middle">{label}</text>'
  if i<2:t+=f'<path d="M225 {y+54}v26m-5-7 5 7 5-7" stroke="currentColor" fill="none"/>'
 return t+'</svg><figcaption>Schéma logique original Sol2026, sans anatomie générée. '+caption+'</figcaption></figure>'
S=[]
S.append(sec(1,'Un œdème qui masque la fonte','''<p>Une enfant fictive de dix-huit mois arrive pour diarrhée et refus de manger. Ses pieds sont gonflés, mais les bras sont très fins et la courbe de croissance s’est infléchie. Son poids paraît moins inquiétant que son état : l’eau des œdèmes peut masquer une perte de tissus. Le premier enjeu est de repérer une urgence, puis de caractériser ensemble l’émaciation et l’œdème, sans conclure à une cause nutritionnelle sur le seul aspect [S3, S4, S6].</p><p>Le kwashiorkor avec marasme associe les signes d’une forme œdémateuse et ceux d’une émaciation importante. On ne soigne pas deux maladies indépendantes l’une après l’autre : on évalue un enfant vulnérable dont les besoins nutritionnels, l’infection éventuelle, les pertes digestives et la perfusion doivent être pris en charge de façon coordonnée [S2–S4].</p><p>En Suisse, PROFILES demande notamment d’évaluer l’état nutritionnel, une perte de poids, un œdème, une croissance insuffisante et les difficultés alimentaires de l’enfance. Le lien avec E42 est pédagogique ; ce n’est ni une correspondance officielle entre classification et objectif fédéral, ni une question d’examen garantie. La vignette est originale [S16].</p>''','L’œdème peut rendre la dénutrition moins visible. Chercher d’abord la gravité, puis mesurer et expliquer les deux composantes [S3, S4].'))
S.append(sec(2,'Définition, périmètre et classification','''<p>Le libellé suisse local de la classification2024 est « Kwashiorkor avec marasme ». E42 ne comporte pas de sous-code dans ce catalogue. Les notes allemandes incluent une malnutrition protéino-énergétique grave de forme intermédiaire ou présentant simultanément les signes du kwashiorkor et du marasme [S1, S2].</p>'''+table(['Catégorie','Ce qu’elle décrit','Prudence'],[['E40','Kwashiorkor : œdème nutritionnel et autres signes possibles.','Un poids proche de la moyenne n’est pas une condition obligatoire ; l’œdème ne dit pas seul s’il existe une fonte.'],['E41','Marasme nutritionnel avec émaciation.','La présence d’un œdème nutritionnel associé fait rechercher une forme mixte.'],['E42','Signes simultanés ou forme intermédiaire.','Documenter les signes, les mesures et la cause ; pas de diagnostic sur albumine seule.'],['E43','Malnutrition protéino-énergétique grave sans précision.','Ne remplace pas une forme mixte effectivement décrite ; comprend un œdème de famine non précisé.']])+'''<p>La terminologie actuelle de l’OMS parle d’émaciation et/ou d’œdème nutritionnel. Chez les enfants de six à cinquante-neuf mois, une émaciation sévère correspond à un poids pour la taille ou la longueur inférieur à trois écarts-types sous la médiane, ou à un périmètre brachial inférieur à115mm. L’œdème nutritionnel bilatéral suffit aussi à classer une malnutrition aiguë sévère. Pour parler de la forme mixte, il faut reconnaître également l’émaciation [S2–S4].</p><p>Le mot « aiguë » n’implique pas nécessairement un début récent : les facteurs causaux peuvent évoluer depuis longtemps. Retard statural, poids insuffisant pour l’âge, émaciation et œdème décrivent des dimensions différentes, parfois simultanées. Les notes générales de codage et les seuils de décision clinique gardent leurs objectifs propres [S2, S3].</p>''','E42 désigne un tableau mixte documenté. Ni un œdème isolé, ni une albumine basse, ni le seul code ne suffisent à raconter la situation [S2–S4].'))
S.append(sec(3,'Épidémiologie : le bon indicateur et le bon dénominateur','''<p>Aucune incidence suisse contemporaine de la forme mixte E42 n’est établie dans les lectures ciblées. Cela ne démontre pas son absence : une présentation rare peut être liée à une maladie digestive, à des difficultés alimentaires ou à une vulnérabilité sociale. Les fréquences de dénutrition hospitalière, d’émaciation mondiale et de kwashiorkor ne sont pas interchangeables [S3, S6, S15].</p><p>Les estimations conjointes UNICEF, OMS et Banque mondiale publiées en2025 décrivent pour2024 environ42,8millions d’enfants de moins de cinq ans avec une émaciation, soit6,6%, dont12,2millions avec une émaciation sévère. Ce sont des estimations de prévalence largement fondées sur des enquêtes, pas le nombre de tous les épisodes survenant au cours d’une année. Elles ne donnent pas directement la fréquence des œdèmes ni des formes mixtes [S15].</p><p>Les séries hospitalières sélectionnent souvent les cas compliqués ; les programmes ambulatoires sélectionnent autrement. Une mortalité observée dans une cohorte ne devient donc pas le risque d’une enfant suivie en Suisse, ni une hiérarchie universelle entre marasme, kwashiorkor et forme mixte [S3, S4, S8].</p><p>Dans l’étude moléculaire publiée en octobre2026 au Niger, soixante enfants par groupe ont été recrutés selon un plan cas-témoins. Les enfants œdémateux y regroupent aussi les formes avec émaciation. Un tel échantillonnage n’est pas un sondage de prévalence et ne permet pas d’isoler une fréquence E42 [S8].</p>''','Une prévalence d’émaciation n’est ni une incidence annuelle, ni une mesure des seules formes mixtes. Toujours préciser population et recrutement [S8, S15].'))
S.append(sec(4,'Du fonctionnement normal aux pertes de réserve','''<p>Les apports alimentaires fournissent énergie, acides aminés, acides gras et micronutriments. Le tube digestif doit permettre digestion et absorption, le foie transforme et distribue les substrats, et les tissus utilisent ou stockent ces ressources. Une réserve corporelle ne se lit pas sur une seule concentration sanguine [S6, S7, S14].</p><p>Quand les apports restent insuffisants, l’organisme mobilise glycogène, graisse et protéines, tout en réduisant certaines dépenses et la croissance. Cette adaptation peut limiter temporairement les besoins sans rendre le déficit sans danger. Fonte musculaire, faiblesse et perte de graisse deviennent visibles ; l’infection et les pertes digestives peuvent accélérer le déséquilibre [S6, S7].</p><p>Dans la forme œdémateuse, une hypoalbuminémie peut contribuer aux mouvements d’eau, mais n’explique pas seule tout le tableau. L’intégrité des barrières, le drainage lymphatique, l’inflammation et la matrice des tissus sont aussi étudiés. Les associations moléculaires récentes restent des pistes, pas une démonstration d’un mécanisme unique ni une indication de perfuser systématiquement de l’albumine [S8, S9].</p><p>La réalimentation change encore la situation : la sécrétion d’insuline et l’utilisation des glucides augmentent, avec des besoins en phosphate, potassium, magnésium et thiamine. Des réserves épuisées peuvent se révéler par des anomalies sanguines et une défaillance d’organes. L’œdème déjà présent avant les apports et un œdème qui s’aggrave pendant la renutrition ne s’interprètent donc pas automatiquement de la même façon [S6, S7].</p>'''+logical('Apports, absorption et besoins','Réserves, tissus et échanges d’eau','Mesures puis soins coordonnés','Les voies sont multiples ; ce schéma ne quantifie pas une cause d’œdème et ne représente pas une anatomie [S6–S8].'),'Comprendre la réserve, la fonction et les échanges d’eau explique pourquoi le poids et l’albumine ne suffisent pas [S6–S8].'))
S.append(sec(5,'Causes, formes et facteurs qui s’entretiennent','''<p>Une disponibilité alimentaire insuffisante, un sevrage mal accompagné, une alimentation peu diversifiée, des préparations inadaptées ou des difficultés de prise peuvent réduire les apports. Les conditions économiques, l’accès à l’eau, la sécurité alimentaire et la santé des personnes qui s’occupent de l’enfant font partie de l’histoire médicale ; ils ne sont pas des motifs de jugement moral [S3, S6].</p><p>Une maladie peut réduire l’appétit, augmenter les besoins ou provoquer des pertes. Diarrhée persistante, infection, maladie digestive, atteinte neurologique ou autre maladie chronique peuvent participer. Plusieurs mécanismes peuvent coexister ; le diagnostic nutritionnel ne dispense jamais de rechercher une cause accessible au traitement [S3, S4, S6].</p><p>La forme mixte comporte des signes de fonte et un œdème nutritionnel. Les lésions de peau, les changements des cheveux et une hépatomégalie peuvent orienter mais ne sont pas obligatoires pour reconnaître une urgence. L’absence d’un aspect « typique » ne suffit pas à rassurer, et une alimentation dite riche en calories ne prouve pas la couverture de tous les besoins [S2, S4, S6].</p><p>Les modèles de carence protéique isolée ont une valeur historique mais ne résument pas les connaissances actuelles. La réponse de l’hôte, les infections, les barrières et les échanges moléculaires sont étudiés ; aucune mutation ou composition de microbiote n’est actuellement nécessaire aux critères cliniques de l’OMS. Les résultats animaux ne deviennent pas un test ou un traitement validé de la forme mixte [S3, S8, S9].</p>''','Chercher comment apports, maladie et environnement se combinent. Le phénotype ne remplace ni l’enquête causale ni l’écoute de la famille [S3, S4, S6].'))
S.append(sec(6,'Anamnèse : reconstruire l’évolution sans culpabiliser','''<p>Reprendre les courbes, les anciens poids et les dates des œdèmes, de la diarrhée, de la fièvre et de la baisse d’appétit. Demander ce qui était réellement préparé, proposé, accepté et absorbé, avec des quantités et des fréquences aussi concrètes que possible. Une prise présentée comme abondante peut être peu énergétique, mal diluée, vomie ou partagée [S3, S4, S6].</p><p>Chez le nourrisson, observer l’allaitement ou la préparation des substituts plutôt que se limiter à « allaitement oui/non ». Rechercher difficultés de succion, déglutition, douleur, fatigue, refus alimentaire ou besoin d’aide. L’OMS insiste sur l’évaluation du couple nourrisson-personne qui s’en occupe, y compris santé physique, santé mentale et soutien disponible [S3].</p><p>Explorer infections et expositions, traitements, maladies digestives ou chroniques, antécédents et trajectoire du développement. Devant un œdème, des urines anormales, un gonflement matinal des paupières, une cardiopathie ou des signes de maladie hépatique peuvent conduire à d’autres hypothèses, sans exclure une dénutrition associée [S4, S6, S10, S11].</p><p>Enfin, demander si les aliments prescrits, l’eau sûre, les visites de suivi et les médicaments sont accessibles. Les conseils doivent tenir compte de la langue, des gestes possibles et des ressources. Documenter l’obstacle et organiser une aide concrète est plus utile que noter simplement une « mauvaise observance » [S3, S4].</p>''','Une chronologie précise et des gestes observés révèlent les mécanismes. Les difficultés matérielles et relationnelles font partie du soin [S3, S4, S6].'))
S.append(sec(7,'Examen clinique : voir, mesurer et interpréter','''<div data-semiology-clinical="E42"><p>La sémiologie clinique relie fonte, œdème, état général et signes de complication. Commencer par conscience, respiration, perfusion, température et glycémie ; poursuivre par les mesures et l’examen des organes. Un enfant malnutri peut être infecté sans présenter une fièvre ou une réaction habituelle [S3, S4, S9].</p></div><p>Rechercher un godet sur les deux pieds : après pression puis relâchement, une dépression persistante traduit un œdème prenant le godet. Décrire symétrie et extension, puis peau, cheveux, masses musculaires et graisse sous-cutanée. Un œdème bilatéral n’est appelé nutritionnel qu’après confrontation au contexte et aux autres causes, notamment rénales [S3, S4, S10].</p><p>Mesurer poids, taille ou longueur avec le matériel approprié, puis périmètre du bras gauche au milieu du bras relâché, ruban au contact sans comprimer. Reporter sur les références adaptées, avec mesures sériées. Le poids est augmenté par l’eau ; une baisse pendant la résolution de l’œdème ne prouve pas à elle seule une perte nutritionnelle supplémentaire [S3, S4, S6].</p><p>Évaluer bouche, peau, respiration, abdomen, foie, état neurologique, signes infectieux et diurèse. La perte de tissu peut modifier le pli cutané et l’aspect des yeux, tandis que l’œdème peut masquer la déshydratation. L’histoire des pertes, la perfusion et les réévaluations comptent davantage qu’un signe isolé présenté comme infaillible [S3, S4].</p>''','Le godet, les mesures et les signes de perfusion répondent à des questions différentes. Leur interprétation reste clinique et répétée [S3, S4, S10].'))
S.append(sec(8,'Urgences et complications : ne pas attendre la renutrition','''<p>Incapacité de boire ou téter, vomissement de tout apport, convulsions, léthargie ou inconscience sont des signes de danger. Détresse respiratoire, choc, hypoglycémie, hypothermie, anémie grave ou infection sévère imposent un niveau de soins adapté. La prise en charge vitale précède les calculs d’apport et ne se réduit pas à administrer une pâte thérapeutique [S3, S4].</p><p>Chez l’enfant de six à cinquante-neuf mois, l’OMS recommande l’hospitalisation en présence de signes de danger, de problème médical aigu, d’œdème nutritionnel sévère (+++) ou d’échec au test d’appétit. Le manuel MSF retient notamment l’extension de l’œdème jusqu’au visage parmi les complications graves ; ces descriptions doivent être utilisées dans leur protocole, sans fabriquer une gradation commune à toutes les publications [S3, S4].</p><p>Une infection sévère peut se révéler par abattement, hypothermie, hypoglycémie ou difficulté respiratoire sans fièvre franche. Un traitement anti-infectieux hospitalier et le soutien des fonctions sont alors organisés rapidement ; l’amoxicilline orale de routine d’un programme nutritionnel ne suffit pas à traiter tout sepsis [S4, S12].</p><p>À l’introduction ou à l’augmentation des apports, surveiller faiblesse nouvelle, tachycardie, tachypnée, anomalies neurologiques et aggravation des œdèmes. Le syndrome de renutrition combine parfois perturbations électrolytiques, manque de thiamine et rétention hydrosodée. Une hypophosphatémie seule ne définit pas toute la gravité et d’autres causes doivent rester envisagées [S6, S7].</p>''','Traiter immédiatement les menaces vitales et rechercher leur cause. La nutrition est indispensable, mais ne remplace pas la réanimation d’une complication [S3, S4, S7].'))
S.append(sec(9,'Diagnostic : confirmer les composantes et rechercher une autre cause','''<p>Après le triage, documenter l’émaciation, l’œdème et le contexte nutritionnel. Chez les six à cinquante-neuf mois, périmètre brachial et poids pour la taille ou la longueur apportent des critères utiles, mais l’eau et une déshydratation aiguë peuvent modifier les mesures. L’examen et la trajectoire évitent de transformer une valeur ponctuelle en diagnostic complet [S2–S4].</p>'''+table(['Hypothèse','Indice et examen utile','Limite'],[['Forme mixte nutritionnelle','Fonte et œdème nutritionnel simultanés, histoire et croissance.','Pas besoin d’une dermatose, pas de seuil d’albumine définissant E42.'],['Syndrome néphrotique','Bandelette puis quantification de la protéinurie, fonction rénale et albumine.','L’œdème au godet peut être semblable ; une dénutrition peut coexister.'],['Perte digestive de protéines','Contexte digestif, albumine et recherche ciblée de perte fécale.','Une alpha-1-antitrypsine fécale n’indique pas seule le site ou la cause.'],['Atteinte cardiaque, hépatique ou fuite capillaire','Examen, histoire et explorations orientées vers l’organe ou l’infection.','Ne pas tout attribuer à l’alimentation ni demander le même bilan à tous.']])+'''<p>Le syndrome néphrotique pédiatrique associe une protéinurie de rang néphrotique à une hypoalbuminémie, ou à un œdème si l’albumine n’est pas disponible. Une bandelette positive conduit à une quantification, de préférence sur urine matinale. Ce raisonnement ferme une lacune importante : l’œdème bilatéral n’est pas, par lui-même, la preuve d’une cause nutritionnelle [S10].</p><p>Les pertes digestives, les défauts de synthèse, l’inflammation et la dilution peuvent aussi abaisser l’albumine. Le bilan s’oriente selon la situation ; la biopsie digestive n’est ni une condition de diagnostic de E42, ni une manière de retarder le traitement d’une complication [S3, S11].</p>''','Établir les deux composantes, puis leur cause. Une albumine basse ne départage pas à elle seule nutrition, perte rénale, perte digestive et inflammation [S3, S10, S11].'))
S.append(sec(10,'Traitement nutritionnel : une progression guidée par l’état','''<p>Le lieu de traitement dépend de la gravité et de la possibilité d’un suivi sûr. Une forme sans complication, avec appétit conservé et évaluation suffisante, peut relever d’un programme ambulatoire ; une forme compliquée demande stabilisation hospitalière. Le plan inclut soins médicaux, aliments thérapeutiques et soutien de la famille [S3, S4].</p><p>En stabilisation, les laits thérapeutiques comme F-75 permettent des apports adaptés à une physiologie fragile. Le volume, les prises, les apports liquides associés et la surveillance sont prescrits selon le protocole et l’état, particulièrement si l’œdème est important. Un volume unique de130ml/kg/j recopié d’une revue ne constitue pas une ordonnance pour tous les enfants œdémateux [S3, S4, S6].</p><p>Après stabilisation, retour de l’appétit et réduction de l’œdème, la transition augmente les apports de façon tolérée. L’OMS décrit en hospitalisation une transition vers l’aliment thérapeutique prêt à l’emploi sur deux à trois jours, avec100–135kcal/kg/j pendant cette transition. Ce stade n’est pas identique au traitement ambulatoire de rattrapage [S3].</p><p>En ambulatoire chez les six à cinquante-neuf mois, l’OMS2023 propose deux options :150–185kcal/kg/j jusqu’à récupération anthropométrique et disparition de l’œdème ; ou la même quantité initiale, puis100–130kcal/kg/j lorsque l’enfant n’est plus sévèrement émacié et n’a plus d’œdème, jusqu’à récupération. Le choix de réduire dépend du programme, de la sécurité alimentaire et du suivi ; il ne s’agit pas d’une réduction obligatoire après guérison [S3].</p><p>Poursuivre l’allaitement lorsque présent, assurer les besoins en eau et vérifier la préparation des produits. Une prise insuffisante, une intolérance, une infection ou une stagnation demande réévaluation. Aucun aliment spécialisé ne traite seul un trouble de déglutition, une malabsorption ou un sepsis [S3, S4, S6].</p>''','Stabilisation, transition et rattrapage ont des objectifs distincts. Augmenter ou réduire les apports selon un protocole complet et la réponse réelle [S3, S4].'))
S.append(sec(11,'Médicaments et liquides : ne pas mélanger les protocoles','''<p>Les aliments thérapeutiques couvrent une partie importante des micronutriments. Vérifier leur composition avant d’ajouter systématiquement vitamines, zinc ou autres suppléments. L’OMS ne recommande pas de forte dose supplémentaire de vitamine A si des aliments conformes en apportent déjà suffisamment ; une indication spécifique reste évaluée [S3, S4].</p><p>L’amoxicilline orale de routine recommandée dans certains programmes sévères non compliqués est différente du traitement d’une infection identifiée ou d’un sepsis. Le manuel MSF2024 donne50mg/kg par prise, deux fois par jour, maximum1g par prise, pendant cinq à sept jours. La FI suisse de la suspension axapharm donne chez l’enfant jusqu’à40kg une plage de50–100mg/kg/j en trois à quatre prises et ne cite pas E42 comme indication spécifique. Population, fréquence et contexte restent explicités, sans nouvelle posologie composite [S3, S4, S12].</p><p>Pour la déshydratation sans choc, l’OMS2023 préfère ReSoMal sous surveillance en structure de santé ; une solution de réhydratation orale de faible osmolarité peut être utilisée si ReSoMal n’est pas disponible. Le choléra suspecté ou une diarrhée aqueuse profuse demandent la solution standard, non davantage diluée. Le choc et l’intolérance nécessitent une stratégie hospitalière adaptée [S3–S5].</p><p>Les essais GASTROSAM2025/2026 remettent en question certaines restrictions traditionnelles. Ils n’ont pas établi de différence de mortalité entre stratégies et n’ont pas observé de surcharge, mais les formes œdémateuses étaient peu nombreuses et la surveillance étroite. Ces données ne justifient ni une interdiction absolue de toute perfusion, ni une prescription automatique de gros volumes pour toute E42 [S17–S19].</p><p>La thiamine et les électrolytes sont évalués dans le risque de renutrition. Les doses adultes d’un consensus suisse et les doses de Benerva dès douze ans ne sont pas des doses de nourrisson. La correction dépend du produit, de la voie, des reins, du bilan et du protocole ; une valeur sanguine normale peut coexister avec des réserves réduites [S7, S13].</p>''','Choisir un protocole applicable et un produit exact. Ne pas assembler une dose, une fréquence et une population provenant de trois sources différentes [S3, S4, S7, S12, S13].'))
S.append(sec(12,'Suivi, transfert et prévention des rechutes','''<p>Le transfert de l’hôpital vers l’ambulatoire repose sur l’amélioration clinique, l’appétit et la résolution suffisante des complications, avec œdème en diminution et plus de grade+++. L’OMS demande notamment l’absence de signes de danger depuis24–48heures chez les six à cinquante-neuf mois. Un poids cible ou un périmètre donné ne remplace pas ces critères de transfert [S3].</p><p>La fin du traitement nutritionnel est une autre décision. Pour les six à cinquante-neuf mois, la recommandation OMS2023 exige poids pour la taille ou la longueur au moins à−2écarts-types et périmètre brachial au moins125mm, observés sur au moins deux visites ou mesures consécutives, ainsi qu’absence d’œdème à deux visites ou mesures consécutives. Les problèmes médicaux et sociaux persistants doivent être orientés. Le pourcentage de gain pondéral n’est pas un critère de sortie [S3].</p><p>Le manuel MSF2024 présente une règle opérationnelle avec poids pour la taille supérieur à−2 ou bras supérieur à125mm, absence d’œdème et au moins deux semaines. Cette différence est conservée comme telle : les opérateurs suivent leur programme validé, et le cours ne fusionne pas « et », « ou », deux visites et deux semaines en une formule fictive [S3, S4].</p><p>Le suivi évalue croissance, alimentation, maladies associées, développement, disponibilité des aliments et capacité d’accès aux soins. Une récupération de poids ne prouve pas à elle seule une récupération complète de la fonction immunitaire. La continuité et l’aide concrète à la famille réduisent les risques de rupture, sans promettre une prévention absolue des rechutes [S3, S4, S9].</p>''','Quitter l’hôpital ne signifie pas finir le traitement. Les critères de sortie gardent leur source et le suivi continue après la récupération [S3, S4].'))
S.append(sec(13,'Âges particuliers et pratique suisse','''<p>Avant six mois, ne pas appliquer automatiquement les seuils et schémas des six à cinquante-neuf mois. Un œdème nutritionnel ou une perte de poids récente justifie l’admission selon l’OMS2023. L’évaluation concerne le nourrisson et la personne qui s’en occupe, l’efficacité de l’allaitement ou du remplacement et les besoins de soutien [S3].</p><p>Chez un nourrisson hospitalisé avec œdème, les compléments décrits sont une formule infantile du commerce ou F-75 en complément du lait maternel. Le F-100 à pleine concentration n’est pas donné en présence d’instabilité, diarrhée, déshydratation ou œdème nutritionnel, notamment du fait de sa charge rénale et du risque de déshydratation hypernatrémique. Les volumes ne sont pas déduits du schéma de l’enfant plus âgé [S3].</p><p>Après cinq ans, chez l’adolescent ou l’adulte, l’anthropométrie et le protocole nutritionnel doivent être adaptés. Le consensus suisse de renutrition de2019 concerne des patients médicaux adultes et exclut les troubles alimentaires ; ses repères ne sont pas une prescription infantile ni un protocole universel d’anorexie mentale [S7].</p><p>Maladie rénale, hépatique, cardiaque, infection ou difficultés de déglutition modifient les besoins, les risques et le choix de voie. Pour un médicament, grossesse et allaitement se lisent dans la FI du produit réel : la nécessité de nutrition ne crée pas une autorisation générale de toutes les doses et molécules [S6, S7, S12, S13].</p><p>En Suisse, documenter les constatations, le plan et les responsabilités, organiser pédiatrie, diététique et aide sociale selon les besoins. Les références de classification2024 et PROFILES2017 gardent leur date ; le cours ne certifie ni remboursement individuel, ni disponibilité de tout aliment spécialisé, ni correspondance officielle avec une question fédérale [S1, S16].</p>''','L’âge, la maladie associée et la formulation changent la décision. Un protocole utile dans une population n’est pas une recette pour toutes [S3, S7, S12, S13].'))
S.append(sec(14,'Critères utiles et pièges de raisonnement',table(['Question','Repère et population','Ce qu’il ne signifie pas'],[['Émaciation sévère,6–59mois','Poids/taille ou longueur<−3écarts-types, ou bras<115mm.','Pas seuil de nourrisson de tout âge ni diagnostic de la cause.'],['Forme mixte','Fonte et œdème nutritionnel simultanés ou forme intermédiaire documentée.','Pas tout œdème au godet ni toute hypoalbuminémie.'],['Fin de traitement OMS2023','Poids/taille≥−2 et bras≥125mm sur deux mesures, sans œdème sur deux mesures.','Pas le même événement que transfert hospitalier ; pas pourcentage de gain pondéral.'],['Apport ambulatoire OMS','150–185kcal/kg/j ; éventuelle réduction100–130 selon option et état.','Pas réduction obligatoire seulement après guérison.'],['Mécanismes récents','Signatures matrice/sphingolipides associées à œdème dans une étude.','Pas causalité établie, biomarqueur E42 validé ou traitement ciblé.']])+'''<p>Les erreurs qui changent les soins sont de se fier à un poids rassurant gonflé d’eau, d’exclure une infection parce qu’il n’y a pas de fièvre, de diagnostiquer une cause nutritionnelle sur l’albumine, de confondre transfert et guérison, ou de reprendre une dose adulte pour un nourrisson. Chaque donnée doit garder sa méthode, son âge et sa source [S3, S4, S7, S10, S12, S13].</p><p>Les études récentes améliorent les connaissances mais ne rendent pas toutes les incertitudes caduques. Un essai sans événement de surcharge ne prouve pas un risque nul ; une association moléculaire ne prouve pas un mécanisme unique ; une cohorte de trois groupes de même taille ne mesure pas la prévalence. Expliquer ces limites fait partie d’un raisonnement précis [S8, S17–S19].</p>''','Connaître les seuils sert à décider ; connaître leurs limites évite de décider pour la mauvaise population [S3, S4, S7, S8].'))
E=[]
E.append(sec('e-1','Mesurer la croissance et les deux composantes',table(['Mesure','Question','Interprétation'],[['Poids et courbe','Quelle évolution avant et pendant la maladie ?','L’eau augmente le poids ; les pertes digestives peuvent le diminuer rapidement.'],['Taille ou longueur','Quelle croissance et quel poids pour cette taille ?','Matériel adapté, position et référence sont nécessaires ; ne pas confondre poids pour âge et poids pour taille.'],['Périmètre brachial','Existe-t-il une émaciation sévère chez les6–59mois ?','Moins de115mm est un seuil utile, pas une mesure sans erreur ni une cause.'],['Œdème','Est-il bilatéral, prenant le godet et de cause nutritionnelle probable ?','Décrire extension, symétrie et évolution ; chercher les autres causes.']])+'''<p>Un examen répété après correction des pertes ou diminution de l’œdème peut modifier la lecture du poids. Documenter l’état hydrique de chaque mesure, plutôt que déclarer toute variation comme gain ou perte de tissu. Le même matériel et une technique reproductible rendent la série plus utile [S3, S4, S6].</p>''','Mesurer permet de suivre ; interpréter exige de savoir ce qui a changé dans l’eau et les tissus [S3, S4].'))
E.append(sec('e-2','Biologie : complications et diagnostics différentiels','''<p>La glycémie est une mesure immédiate si l’enfant est malade ou présente des signes de danger. Le bilan des électrolytes, du phosphate, du magnésium, de la fonction rénale et de l’état infectieux dépend de la gravité et du contexte. La surveillance est rapprochée lors de la renutrition ; un résultat initial normal n’exclut pas un manque de réserve [S4, S6, S7].</p><p>Albumine, protéines et bilan hépatique peuvent aider à comprendre un œdème ou une maladie associée. L’albumine est aussi influencée par l’inflammation, la dilution et les pertes : elle ne suffit pas à classer une forme nutritionnelle ni à mesurer directement l’apport alimentaire. Une protéinurie ou une perte digestive demande son raisonnement propre [S6, S10, S11].</p><p>Dans le diagnostic différentiel pédiatrique, IPNA définit la protéinurie de rang néphrotique par un rapport protéines/créatinine urinaires au moins200mg/mmol, ou des critères de collecte équivalents. Associée à albumine inférieure à30g/l, ou à un œdème si l’albumine n’est pas disponible, elle définit un syndrome néphrotique. La bandelette dépiste ; la quantification confirme. Ce seuil ne définit pas E42 [S10].</p><p>Devant une suspicion de perte digestive de protéines, la recherche fécale d’alpha-1-antitrypsine et sa clairance peuvent être utiles selon le contexte. Elles ne révèlent pas seules la cause et n’identifient pas toujours une fuite gastrique. Le choix du test suit l’hypothèse [S11].</p>''','La biologie recherche surtout complications et causes associées ; aucune albumine seuil ne remplace la description clinique de la forme mixte [S6, S10, S11].'))
E.append(sec('e-3','Explorations ciblées et limites des marqueurs récents','''<p>Urines, microbiologie, recherche de tuberculose ou d’une autre infection, bilan digestif et exploration cardiaque ou hépatique sont orientés par l’histoire et l’examen. Il ne s’agit pas d’un catalogue obligatoire à demander pour tout enfant. Une infection peut nécessiter des soins avant une confirmation complète [S3, S4, S10, S11].</p><p>L’imagerie ou l’endoscopie peuvent répondre à une hypothèse spécifique de maladie d’organe ; elles ne sont pas des critères universels de E42. Une micrographie normale sert à comprendre l’absorption, pas à poser le diagnostic individuel. Une biopsie n’est pas demandée pour simplement constater l’émaciation [S3, S11, S14].</p><p>L’étude de2026 sur les protéines de matrice et les lipides a comparé des groupes d’enfants sélectionnés, sans séparer les formes mixtes des autres formes œdémateuses. Les différences observées sont exploratoires et n’ont pas de seuil clinique validé pour diagnostiquer E42. Ni analyse de microbiote ni séquençage génétique ne remplacent actuellement l’évaluation clinique et anthropométrique décrite par l’OMS [S3, S8, S9].</p>''','Un examen devient utile s’il répond à une question et peut modifier les soins. Un marqueur de recherche n’est pas automatiquement un test disponible ou validé [S3, S8, S10, S11].'))
quizzes=[('Un enfant de dix-huit mois a un bras mesuré à105mm et des œdèmes bilatéraux au godet. Quelle démarche ?','Rechercher la gravité, confirmer les composantes et évaluer la cause nutritionnelle ainsi que les autres causes d’œdème.','Conclure sur l’œdème seul et ne pas mesurer la croissance.','La fonte et l’œdème peuvent coexister, mais un œdème bilatéral peut aussi avoir une cause rénale ou autre. Le triage et l’enquête restent nécessaires [S2–S4, S10].'),('Le poids baisse pendant que l’œdème diminue sous traitement. Que conclure ?','Interpréter avec état hydrique, prises et évolution clinique ; la baisse peut correspondre à une perte d’eau.','Déclarer nécessairement un échec nutritionnel parce que tout poids perdu est du muscle.','Eau et tissu contribuent au poids. Une mesure isolée ne départage pas leur évolution [S3, S4, S6].'),('L’enfant est stable et transférable vers l’ambulatoire. Est-ce la fin du traitement nutritionnel ?','Non ; le transfert clinique et la fin du traitement ont des critères distincts et nécessitent une continuité organisée.','Oui ; quitter l’hôpital signifie que tous les critères anthropométriques de sortie sont atteints.','L’OMS distingue transfert et fin du programme. Les critères de fin chez6–59mois gardent les deux mesures anthropométriques et l’absence d’œdème répétées [S3].'),('Que prouvent les essais récents sans surcharge observée pendant la réhydratation ?','Ils apportent des données utiles mais ne garantissent pas un risque nul dans toute forme mixte et toute situation.','Ils autorisent à appliquer un volume intraveineux unique à tout enfant E42, sans surveillance.','Peu d’enfants avaient un œdème et les équipes assuraient un suivi étroit. Absence d’événement, équivalence universelle et absence de risque ne sont pas synonymes [S17–S19].')]
qb=''
for q,right,wrong,fb in quizzes:qb+='<div class="quiz ui"><p><b>Cas pédagogique fictif.</b> '+q+'</p><button data-ok="0">'+wrong+'</button><button data-ok="1">'+right+'</button><p class="fb" hidden>'+fb+'</p></div>'
E.append(sec('e-4','Quatre exercices pour relier signes et décisions',qb,'Une bonne réponse explique ce que les signes permettent de conclure, et ce qu’ils ne prouvent pas [S3, S4, S17–S19].'))
# Human published original, inspected before copying; no generated anatomy.
asset=R/'assets/img/e42/alpha/codex/intestine-openstax2013.jpg';asset.parent.mkdir(exist_ok=True,parents=True);shutil.copyfile(C/'intestine-openstax2013.jpg',asset);(D/'figures').mkdir(exist_ok=True);shutil.copyfile(asset,D/'figures/intestine-openstax2013.jpg')
def humanfig():return '''<figure><div data-e42-frame="1"><img src="assets/img/e42/alpha/codex/intestine-openstax2013.jpg" alt="Planche humaine publiée montrant plis, villosités et microvillosités de l’intestin grêle normal ; quatre repères décrits dans la légende." loading="eager"><span data-e42-marker="1" data-e42-pin="1">1</span><span data-e42-marker="1" data-e42-pin="2">2</span><span data-e42-marker="1" data-e42-pin="3">3</span><span data-e42-marker="1" data-e42-pin="4">4</span></div><figcaption>Original humain OpenStax College, Connexions,19juin2013 ; micrographies b–d fournies par les Regents of University of Michigan Medical School©2012. <a data-reference-source="1" href="https://commons.wikimedia.org/wiki/File:2418_Histology_Small_IntestinesN.jpg" target="_blank" rel="noopener">Planche2418, Creative Commons Attribution3.0</a>. Pixels inchangés ; repères français superposés :1plis circulaires,2villosités,3microvillosités,4chylifère dans le schéma. Même original utilisé dans anatomie et histologie, pas deux originaux distincts. Tissu normal, pas biopsie E42. La notice du manuel indique microscope optique56× et508×, électronique196000× ; ces grossissements ne calibrent pas l’écran. Coloration non établie dans la notice, labels anglais complétés par cette légende [S14, S20].</figcaption></figure>'''
units={}
semio=[
('normal','Normal : réserves et croissance','''Un enfant en croissance reçoit et absorbe les nutriments nécessaires aux fonctions et à la construction des tissus. La courbe décrit une trajectoire, tandis que les mesures de poids, longueur et bras apportent des informations complémentaires. L’eau participe aussi au poids ; elle ne représente pas une réserve musculaire ou graisseuse. Un examen normal est toujours situé dans l’âge et le contexte, sans confondre petite taille constitutionnelle et perte récente de tissu [S3, S6, S14].'''),
('signs','Signes et symptômes','''La fonte musculaire et la perte de graisse peuvent coexister avec un œdème bilatéral prenant le godet. Chercher fatigue, baisse d’appétit, diarrhée, difficultés alimentaires, lésions de peau et changements des cheveux, sans exiger chaque signe. L’œdème peut masquer la minceur des membres ou du visage. L’infection peut être peu fébrile ; un comportement inhabituel ou une difficulté respiratoire garde donc toute sa valeur clinique [S3, S4, S6].'''),
('mechanisms','Du mécanisme au signe','''Le manque d’apports ou une maladie réduisent les ressources disponibles, avec mobilisation des réserves et ralentissement de la croissance. Les échanges d’eau et les barrières contribuent au phénotype œdémateux ; l’albumine seule n’en explique pas toutes les différences. Faiblesse et mauvaise tolérance aux apports peuvent refléter plusieurs perturbations. Les pistes moléculaires de matrice et de lipides sont des associations exploratoires, pas une cause unique démontrée chez chaque enfant [S6–S8].'''),
('examination','Examen expliqué','''Commencer par respiration, conscience, perfusion, température et glycémie si l’enfant est malade. Rechercher le godet aux deux pieds et décrire son extension. Mesurer bras gauche relâché, ruban sans compression, puis poids et taille ou longueur avec méthode adaptée. Examiner bouche, peau, abdomen, respiration et diurèse. Les gestes sont expliqués à l’enfant et à l’accompagnant ; une mesure faite rapidement mais sans bonne technique peut égarer [S3, S4, S10].'''),
('interpretation','Interprétation contextualisée','''Chez les six à cinquante-neuf mois, bras inférieur à115mm ou poids pour taille/longueur inférieur à−3écarts-types indique une émaciation sévère selon l’OMS. L’œdème nutritionnel suffit aussi à classer une malnutrition aiguë sévère, mais ne prouve pas sa cause sur simple inspection. Une baisse pondérale sous traitement peut accompagner la disparition de l’eau. Croiser mesures, histoire, examen et évolution évite de confondre quantité de tissu et volume liquidien [S3, S4, S6].'''),
('differentials','Différentiels utiles','''Le syndrome néphrotique peut produire un godet semblable : rechercher et quantifier les protéines urinaires. Une perte digestive, un défaut de synthèse hépatique, une atteinte cardiaque ou une fuite capillaire peuvent aussi contribuer à l’œdème. Une albumine basse ne tranche pas à elle seule. Plusieurs causes et une dénutrition peuvent coexister ; il faut donc éviter à la fois le bilan uniforme de tous les organes et l’étiquette nutritionnelle automatique [S10, S11].'''),
('urgency','Urgence et orientation','''Danger neurologique, impossibilité de boire, choc, détresse respiratoire, hypoglycémie, hypothermie ou infection sévère imposent une évaluation urgente. L’échec du test d’appétit et l’œdème sévère orientent aussi vers l’hospitalisation dans les protocoles de six à cinquante-neuf mois. L’alimentation spécialisée ne remplace pas les soins d’une complication. La déshydratation est réévaluée fréquemment ; les signes habituels peuvent être modifiés par la fonte et l’œdème [S3, S4].'''),
('limits','Limites et relation de soin','''Aucun examen unique ne donne la cause ou toutes les réserves. Les seuils ne se transposent pas directement au nourrisson plus jeune ou à l’adulte ; les références et le matériel comptent. Un retrait relationnel, une difficulté matérielle ou un trouble de l’alimentation demandent une écoute sans culpabilisation. La fin du séjour hospitalier ne termine pas nécessairement le traitement ; expliquer le suivi et vérifier l’accès aux aliments et aux visites font partie de l’examen global [S3, S4, S7].'''),
('sources','Sources, populations et portée','''Les critères cliniques et les décisions sont reliés à la <a data-reference-source="1" href="https://www.who.int/publications/i/item/9789240082830" target="_blank" rel="noopener">directive OMS2023</a> et au <a data-reference-source="1" href="https://medicalguidelines.msf.org/en/viewport/CG/english/severe-acute-malnutrition-16689141.html" target="_blank" rel="noopener">manuel MSF2024</a>. Les recommandations <a data-reference-source="1" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9589698/" target="_blank" rel="noopener">IPNA2022</a> soutiennent le différentiel rénal. Les populations et critères de sortie divergent parfois ; cette leçon les conserve explicitement. Les lectures suisses de produits et de formation n’établissent ni un protocole suisse unique E42 ni une validation médicale humaine [S3, S4, S10, S12, S13, S16].''')]
sem='<section class="ilot" id="e42-s-semio-cours"><h3>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h3><p>Relier un signe à un mécanisme ne consiste pas à lui attribuer une cause certaine. L’enjeu est de comprendre ce qu’il permet de rechercher, de mesurer et de décider dans cette population [S3, S4].</p>'
for key,title,txt in semio:sem+=f'<section class="ilot" id="e42-semio-{key}" data-semiology="{key}"><h3>{title}</h3><p>{txt}</p></section>'
sem+='<div class="key"><b>À retenir.</b> Lire fonte, œdème et évolution ensemble, rechercher urgence puis cause et maintenir un suivi adapté [S3, S4].</div></section>';units['semio']=sem
units['anat']=sec('s-anat-cours','Anatomie : trajet des nutriments et échanges de liquide','''<p>Le tube digestif transforme et absorbe les aliments ; le grêle comprend duodénum, jéjunum et iléon. Sa paroi comporte plusieurs couches et sa muqueuse forme des plis, des villosités et des microvillosités. Ces structures ne sont pas trois noms pour un même relief : les plis comprennent muqueuse et sous-muqueuse, les villosités sont des projections de muqueuse, et les microvillosités se trouvent à la surface apicale des cellules [S14].</p><p>Une villosité contient des vaisseaux sanguins et un chylifère lymphatique. Les sucres et acides aminés absorbés rejoignent le sang portal ; une partie des lipides passe par la lymphe avant de rejoindre la circulation. Cette organisation explique pourquoi absorption, circulation sanguine et drainage lymphatique sont liés mais non équivalents. Les schémas de la planche décrivent le normal, pas le mécanisme certain d’un œdème nutritionnel [S11, S14].</p><p>La graisse sous-cutanée et le muscle constituent des compartiments que l’examen peut apprécier et les mesures suivre indirectement. Dans la forme mixte, la fonte peut être importante alors que le liquide interstitiel augmente le volume des membres. Un contour externe plus arrondi n’assure donc pas que la masse musculaire soit conservée. Le périmètre du bras apporte une information utile, sans être une imagerie directe de la composition de chaque tissu [S3, S4, S6].</p><p>Le foie, les vaisseaux et les voies lymphatiques participent aux échanges et à la distribution des substrats. Les travaux récents sur la matrice des tissus et le drainage sont des pistes : ils ne prouvent pas une lésion anatomique unique dans toute E42. Une atteinte cardiaque, rénale ou digestive peut aussi modifier les échanges, d’où le diagnostic différentiel de l’œdème [S8, S10, S11].</p><p>La démarche anatomique guide les questions : pertes digestives et diarrhée orientent vers le tube digestif, protéinurie vers le rein, signes de congestion vers le cœur. Elle ne justifie pas de demander toute imagerie ni une biopsie systématique. Le traitement doit maintenir des apports absorbables, corriger les complications et rechercher la cause accessible au soin [S3, S4, S10, S11].</p>'''+humanfig(),'Du relief intestinal aux compartiments corporels, la structure explique les signes et les limites du poids. La planche représente le normal [S6, S14].')
units['histo']=sec('s-histo-cours','Histologie : surface d’absorption et barrière','''<p>Au microscope, le grêle normal montre un épithélium simple avec cellules absorbantes, cellules à mucus et autres cellules spécialisées. Les villosités augmentent la surface et les cryptes occupent les espaces qui les séparent. La bordure en brosse correspond à un ensemble de microvillosités apicales ; ce n’est pas une seconde couche de villosités visible à l’œil nu. L’image électronique et les vues optiques montrent donc des échelles différentes [S14].</p><p>La barrière n’est pas une paroi inerte. Les cellules et leur environnement participent à l’absorption, à la sécrétion et à la défense. Une lésion de muqueuse ou une altération de son intégrité peut contribuer à malabsorption, pertes et inflammation. Dans la dénutrition et certaines entéropathies, ces anomalies peuvent entretenir la difficulté à récupérer malgré des aliments proposés [S6, S9, S11].</p><p>Il ne faut pourtant pas déduire une lésion histologique précise du seul code. Les altérations intestinales décrites dans les revues sont hétérogènes et dépendent des maladies, des infections et du recrutement. Une villosité raccourcie n’est pas spécifique de la forme mixte, et les modèles de souris ou de porcelets ne remplacent pas une observation humaine. Le tissu normal montré ici n’est ni une biopsie d’un enfant E42 ni un contrôle apparié à l’étude moléculaire [S8, S9, S14].</p><p>Les pertes digestives protéiques peuvent relever d’une surface muqueuse lésée ou d’un trouble lymphatique. Le dosage fécal ciblé et l’examen de la cause peuvent alors être plus utiles qu’une simple répétition d’albumine. Une endoscopie avec prélèvement reste une décision spécialisée pour une question précise, pas une condition préalable à l’alimentation d’un enfant instable [S11].</p><p>Pour les soins, cette histologie explique pourquoi une diarrhée, un défaut d’absorption ou une infection peuvent demander plus qu’un apport calorique théorique. Les aliments sont choisis selon phase et tolérance ; une mauvaise réponse conduit à réévaluer la cause et la mise en œuvre. La coloration des micrographies n’étant pas précisée dans la notice, elle n’est pas inventée ; leurs grossissements originaux ne sont pas une mesure à effectuer sur l’écran [S3, S4, S14, S20].</p>'''+humanfig(),'La surface et la barrière rendent l’absorption possible. Un mécanisme plausible ne transforme pas une image normale en preuve de lésion individuelle [S9, S11, S14].')
units['physio']=sec('s-physio-cours','Physiologie : adaptation, perfusion et renutrition','''<p>À l’état nourri, les apports permettent d’utiliser et de stocker les substrats tout en soutenant croissance et fonctions. Quand les apports diminuent, la production d’insuline baisse et le métabolisme mobilise progressivement glycogène, protéines et graisse. La dépense et la croissance s’adaptent, mais cette réponse ne supprime ni les besoins essentiels ni le risque infectieux [S6, S7].</p><p>La fonte représente une perte de réserve fonctionnelle autant qu’un changement de poids. Le muscle participe au mouvement et à la respiration ; fatigue, baisse d’activité et moindre tolérance à une maladie peuvent accompagner sa perte. L’état circulatoire dépend aussi de la perfusion et des échanges d’eau, qui ne se lisent pas directement sur la présence ou l’absence d’un œdème. Un enfant œdémateux peut être déshydraté [S3, S4, S6].</p><p>La classification de l’hydratation est difficile parce que yeux creux et pli cutané peuvent être modifiés par la malnutrition. L’histoire de diarrhée, vomissements et apports, la perfusion, la diurèse et les examens répétés servent à suivre une trajectoire. Le poids peut changer rapidement avec l’eau, sans que toute variation représente du tissu reconstitué ou perdu [S3, S4].</p><p>La réalimentation réactive l’utilisation glucidique et l’anabolisme. Des électrolytes entrent dans les cellules, tandis que l’équilibre hydrosodé se modifie. Si les réserves sont basses, un apport trop peu surveillé peut révéler faiblesse, troubles du rythme ou dysfonction respiratoire. Cela ne signifie pas qu’il faut laisser persister une hypoglycémie : l’urgence métabolique et la progression nutritionnelle planifiée répondent à des objectifs différents [S6, S7].</p><p>Les protocoles répartissent ainsi stabilisation, transition et rattrapage. L’enfant sans complication et avec appétit peut entrer directement dans un programme ambulatoire adapté ; l’enfant instable a d’abord besoin de soins hospitaliers. L’efficacité se juge sur l’ensemble clinique, l’alimentation tolérée, la disparition de l’œdème et la récupération mesurée, pas sur un gain pondéral instantané [S3, S4].</p>''','L’adaptation au déficit a ses limites ; le retour des apports exige lui aussi une surveillance physiologique [S3, S4, S6, S7].')
units['bioch']=sec('s-bioch-cours','Biochimie : substrats, cofacteurs et réserves invisibles','''<p>L’oxydation des glucides, des lipides et des acides aminés dépend de réactions enzymatiques et de cofacteurs. Le phosphate intervient dans les molécules énergétiques et de nombreuses réactions ; le magnésium et le potassium participent au fonctionnement cellulaire. La thiamine, transformée en coenzyme, contribue notamment au métabolisme glucidique. Une carence peut devenir particulièrement importante lorsque l’utilisation des glucides augmente [S7, S13].</p><p>La concentration sanguine d’un élément n’est pas la quantité totale disponible dans le corps. Pendant un déficit prolongé, des stocks peuvent diminuer avant qu’un prélèvement ne montre une anomalie majeure. Après réalimentation, les déplacements intracellulaires et les besoins accrus peuvent faire baisser phosphate, potassium et magnésium. Les chiffres servent à adapter la correction, mais leur lecture garde le contexte rénal, acido-basique et médicamenteux [S6, S7].</p><p>L’albumine possède des fonctions de transport et participe à la pression oncotique. Sa concentration dépend aussi de la synthèse, des pertes, de l’inflammation et de la dilution. Elle n’est donc ni une mesure directe du dernier repas ni un test spécifique de E42. Une hypoalbuminémie peut accompagner un syndrome néphrotique, une perte digestive ou une maladie inflammatoire [S6, S10, S11].</p><p>Les analyses de2026 ont identifié dans une cohorte des signatures de protéines de matrice et de sphingolipides associées à l’œdème et évoluant avec le traitement. Ces lipides participent à la structure et à la signalisation cellulaires. Les analyses ne prouvent cependant pas si les signatures sont causes, conséquences ou manifestations parallèles d’un processus commun. L’étude n’a pas validé une analyse sanguine de routine spécifique de la forme mixte [S8].</p><p>Le lien clinique est concret : surveiller les complications biochimiques pendant la renutrition, rechercher les causes d’anomalies et vérifier produit, voie et fonction rénale avant supplémentation. Les molécules de recherche ne deviennent pas des compléments universels et l’albumine basse ne constitue pas, seule, une indication de perfusion d’albumine [S7, S8, S10, S11].</p>''','Le bilan est une fenêtre sur un système dynamique. Il ne mesure pas à lui seul les réserves et ne remplace pas les critères cliniques [S6–S8].')
units['gene']=sec('s-gene-cours','Génétique et immunologie : terrain et réponse de l’hôte','''<p>Normalement, les barrières, les cellules de l’immunité innée et celles de l’immunité adaptative coopèrent pour reconnaître et contrôler les agents infectieux. Les cellules présentatrices d’antigènes contribuent à activer les lymphocytes, et les réponses nécessitent énergie et nutriments. Le nombre de cellules dans le sang n’est pas une mesure complète de leur efficacité ni de l’intégrité de la barrière intestinale [S9].</p><p>Dans la malnutrition sévère, des études humaines décrivent des perturbations de présentation antigénique, de réponses cellulaires ou de médiateurs, tandis que d’autres mécanismes proviennent surtout de modèles animaux. Les résultats ne sont pas uniformes : des nombres leucocytaires préservés peuvent coexister avec une fonction altérée. Cela explique la prudence devant un enfant infecté qui ne présente pas une fièvre ou une réaction biologique habituelle [S4, S9].</p><p>La susceptibilité à une forme œdémateuse a conduit à étudier le terrain de l’hôte, l’environnement et le microbiote. Cela ne fait pas de E42 une maladie mendélienne définie par une mutation unique. Les critères de l’OMS reposent sur l’évaluation clinique et anthropométrique ; ils ne demandent pas un séquençage ou une analyse de microbiote. Une maladie génétique sous-jacente peut être recherchée si d’autres arguments la suggèrent, sans devenir l’explication par défaut de toute forme mixte [S3, S6, S9].</p><p>Les travaux moléculaires récents renforcent l’idée d’une réponse complexe impliquant inflammation, matrice et lipides, mais leurs groupes œdémateux ne séparent pas les enfants avec marasme associé. Les analyses de microbiome avaient de petits effectifs et n’ont pas montré de signature spécifique robuste. Un résultat négatif dans ce cadre ne démontre pas que tout rôle du microbiote est absent [S8].</p><p>Pour la clinique et le traitement, retenir la vulnérabilité infectieuse, la nécessité d’une recherche adaptée et la surveillance de la récupération. Une normalisation du poids ne certifie pas la restauration complète de l’immunité ; une efficacité observée chez la souris ou le porc n’autorise pas un probiotique ou une intervention génétique de routine chez l’enfant. Les résultats d’études anciennes et leur qualité doivent rester contrôlés avant toute application [S3, S8, S9].</p>''','Le terrain influence la réponse, sans fournir un test génétique universel E42. Distinguer normal, observations humaines et modèles expérimentaux [S3, S8, S9].')
# Every scientific discipline links normal science with clinical examination and treatment.
bridges={'semio':('Signe et mécanisme','Mesure et interprétation','Orientation et soins','S3, S4'),'anat':('','','','S6, S14'),'histo':('','','','S9, S11, S14'),'physio':('Réserve et adaptation','Perfusion et évolution','Apports selon la tolérance','S3, S4, S7'),'bioch':('Réserves et besoins','Bilan et déplacements','Correction surveillée','S6, S7, S13'),'gene':('Barrière et réponse immune','Infection et signes parfois discrets','Soins et suivi de récupération','S3, S4, S9')}
for k,(a,b,c,ss) in bridges.items():
 bridge='<div class="key"><b>Science → clinique.</b> Comprendre le fonctionnement normal puis sa perturbation aide à interpréter les signes. <b>Science → examen.</b> La question clinique détermine la mesure et ses limites. <b>Science → traitement.</b> Les soins suivent gravité, âge et cause ; aucune observation isolée ne fournit une prescription universelle ['+ss+'].</div>'
 if a:bridge+=logical(a,b,c,'Enchaînement de raisonnement, pas schéma anatomique ni score individuel ['+ss+'].')
 if k=='semio':
  at=units[k].index('</h3>')+5;units[k]=units[k][:at]+bridge+units[k][at:]
 else:units[k]=bridge+units[k]
sc='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">';labels=[('semio','Sémiologie fondamentale et analytique'),('anat','Anatomie'),('histo','Histologie'),('physio','Physiologie'),('bioch','Biochimie'),('gene','Génétique et immunologie')]
for i,(k,label) in enumerate(labels):sc+=f'<button id="e42-tab-{k}" role="tab" aria-controls="e42-s-{k}" data-s="e42-s-{k}" aria-selected="{str(i==0).lower()}">{label}</button>'
sc+='</div><div class="chap-body sci-body">'
for i,(k,label) in enumerate(labels):sc+=f'<div class="sci" role="tabpanel" aria-labelledby="e42-tab-{k}" id="e42-s-{k}"'+(' hidden' if i else '')+'>'+units[k]+'</div>'
sc+='</div>'+pager+'</div>' if 'pager' in globals() else '</div><div class="pager ui"><button class="prev">← Partie précédente</button><span></span><button class="next">Partie suivante →</button></div></div>'
P=[]
foodtable=table(['Produit et phase','Composition ou apport source','Population et limite'],[['F-75, stabilisation','75kcal et0,9g de protéines pour100ml.','Volume prescrit selon état et protocole ; pas130ml/kg/j universel en œdème sévère.'],['F-100, réhabilitation','100kcal et2,9g de protéines pour100ml.','Après stabilisation ; moins6mois avec œdème/instabilité, pas à pleine concentration.'],['Transition hospitalière vers aliment prêt à l’emploi','100–135kcal/kg/j, transition de2–3jours selon tolérance.','Recommandation OMS maintenue, distincte du rattrapage ambulatoire.'],['Aliment thérapeutique prêt à l’emploi,6–59mois ambulatoires','150–185kcal/kg/j jusqu’à récupération ; ou réduction100–130après disparition émaciation sévère/œdème, jusqu’à récupération.','Deux options, décision du programme et du suivi ; pas réduction obligatoire après guérison.']])
P.append(sec('p-1','Aliments thérapeutiques : dose, phase et composition',foodtable+'''<p>Ces produits sont des aliments à fins médicales spécifiques, pas des médicaments interchangeables au même volume. La composition, la dilution, le mode de préparation, les apports liquides et la conservation se vérifient sur le produit réel et dans le protocole. Ne pas remplacer un lait de stabilisation par un lait plus concentré simplement pour « rattraper » plus vite [S3, S4, S6].</p><p>Les aliments conformes contiennent vitamines et minéraux. Avant d’ajouter vitamine A, zinc ou autres compléments, vérifier ce qui est déjà reçu. Les fortes doses supplémentaires de vitamine A ne sont pas routinières si les aliments conformes en apportent suffisamment. Une indication spécifique doit rester distincte de l’ajout systématique [S3, S4].</p><p>La qualité des soins comprend l’observation de la prise, la poursuite de l’allaitement si présent, la gestion des intolérances et l’accès aux aliments après transfert. Les durées typiques de phase sont des repères de programme, pas un calendrier qui remplace l’état de l’enfant [S3, S4].</p>''','Vérifier la phase et la préparation avant le calcul. Un apport théorique ne garantit ni ingestion, ni absorption, ni sécurité [S3, S4, S6].'))
rehydtable=table(['Source / situation','Choix décrit','Ce qu’il faut éviter'],[['OMS2023,6–59mois sévères déshydratés sans choc','ReSoMal préféré ; solution orale de faible osmolarité si indisponible.','ReSoMal à domicile ou débit sans surveillance.'],['Choléra suspecté ou diarrhée aqueuse profuse','Solution OMS standard de faible osmolarité, préparée normalement.','Dilution supplémentaire ou remplacement automatique par ReSoMal.'],['MSF2022, sachet ReSoMal','84g dans2litres d’eau propre bouillie et refroidie ; utiliser solution dans24h.','Concentrer le sachet, injecter la solution, mélanger les quantités avec un autre produit.'],['Déshydratation grave / choc / intolérance','Évaluation et protocole hospitalier selon perfusion, pertes, voie tolérée et surveillance.','Interdire toute perfusion ou appliquer à tous un volume d’essai clinique.']])
P.append(sec('p-2','Réhydratation : voie, sodium et surveillance',rehydtable+'''<p>Le bilan inclut tous les liquides : réhydratation, laits, eau, perfusions et médicaments. Rechercher réponse clinique, diurèse, poids et signes de surcharge sans attribuer automatiquement un gonflement à une seule cause. L’œdème n’exclut pas un déficit intravasculaire ou une déshydratation par diarrhée [S3–S5].</p><p>Les débits de différents manuels et essais ne sont pas ajoutés. Les protocoles MSF ont leur méthode d’estimation et de réévaluation, tandis que l’OMS2023 énonce un choix de solution et des conditions. L’essai oral GASTROSAM2026 a comparé les solutions avec des volumes, des équipes et une surveillance définis ; ce n’est pas un protocole familial universel [S3–S5, S17].</p><p>Dans l’essai oral, seuls24des415enfants avaient un œdème nutritionnel. Dans l’essai intraveineux,11des272avaient un kwashiorkor. L’absence de surcharge observée et l’absence de différence de mortalité établie doivent donc être interprétées avec prudence pour les formes mixtes, sans nier ces données nouvelles ni certifier une équivalence générale [S17–S19].</p>''','Réhydrater exige de choisir une stratégie complète et de suivre la réponse. Le débat récent ne supprime ni le besoin de liquide ni la surveillance [S3–S5, S17–S19].'))
amoxitable=table(['Référence / population','Dose et rythme','Limite'],[['MSF février2024, 6–59mois, routine nutritionnelle sans infection spécifique','50mg/kg par prise,max1g, deux fois par jour pendant5–7jours, voie orale.','Protocole de programme, pas traitement de tout sepsis ni fréquence de FI suisse.'],['FI axapharm suspension octobre2024, enfant≤40kg','50–100mg/kg/j en3–4prises ; maximum2000mg/j et50mg/kg par prise.','Pas indication spécifique E42 ; volume50mg/ml après préparation.'],['Nouveau-né / prématuré, FI','Parentéral en règle du fait absorption incertaine ; oral au plus tôt dès8jours.','Pas application automatique du schéma6–59mois au nouveau-né.'],['Rein, enfant≤40kg','FI demande une forme parentérale en insuffisance rénale.','Ne pas inventer un intervalle oral infantile à partir du tableau adulte.'],['Rein, adulte/enfant>40kg','Clairance10–30ml/min : maximum500mg toutes12h ;<10 : maximum500mg toutes24h.','Ces plafonds ne sont pas une nouvelle dose E42 ni un tableau de nourrisson.']])
P.append(sec('p-3','Amoxicilline : produit, indication et rythme',amoxitable+'''<p>La formulation lue est Amoxicilline axapharm200mg/4ml, poudre pour suspension orale, soit50mg/ml après préparation, FI octobre2024. Les comprimés dispersibles axapharm d’abord consultés ne sont pas prévus pour les enfants jusqu’à40kg : ils ne servent donc pas de preuve de posologie de cette suspension [S12].</p><p>La dose quotidienne haute du manuel MSF est dans la plage quotidienne de la FI, mais la fréquence n’est pas la même et l’indication nutritionnelle de programme n’est pas une indication spécifique du libellé suisse. Le prescripteur vérifie protocole applicable, germe éventuel, produit et terrain ; il ne combine pas arbitrairement le nombre de prises d’une source avec la durée d’une autre. Vomissements importants, mauvaise absorption ou infection grave peuvent imposer un autre parcours hospitalier [S4, S12].</p><p>Contre-indications : hypersensibilité aux pénicillines/céphalosporines et situations du libellé comme mononucléose ou leucémie lymphoïde. Rechercher réaction immédiate, éruption grave, diarrhée sévère ou sanglante, et atteinte rénale/cristallurie. Méthotrexate, allopurinol et anticoagulants oraux demandent une vérification des interactions ; le suivi est adapté au traitement prolongé [S12].</p><p>La FI demande prudence en grossesse ; elle prévoit de ne pas administrer pendant l’allaitement ou de sevrer si nécessaire. Cette formulation datée reste attribuée au produit, sans devenir une règle universelle de toute amoxicilline : une décision chez une mère allaitante se discute avec le prescripteur. Agiter la suspension et respecter sa conservation maximale de dix jours après préparation [S12].</p>''','Nom, concentration et population sont aussi importants que mg/kg. La routine nutritionnelle ne remplace pas l’évaluation d’une infection grave [S4, S12].'))
thiaminetable=table(['Population / indication','Repère réellement lu','Ce qui ne se transpose pas'],[['Consensus suisse2019, adulte médical à risque de renutrition','Thiamine200–300mg au moins30min avant les apports planifiés ; suivi clinique et biologique.','Pas dose de nourrisson, pas raison de retarder correction d’une hypoglycémie urgente.'],['Benerva FI avril2019, adulte/adolescent dès12ans, prophylaxie','100mg un jour sur deux par voie orale.','Pas protocole universel de prévention de renutrition pédiatrique.'],['Benerva, carence modérée / grave orale','100mg/j modérée ;200–300mg/j grave.','Ces schémas sont ceux de la FI, pas des prises à empiler.'],['Benerva, grave carence parentérale','Jusqu’à200mg/j ; intramusculaire ou intraveineuse très lente, puis orale si possible.','300mg oral ne signifie pas300mg intraveineux ; injection hospitalière avec surveillance.'],['Moins12ans','Utilisation/innocuité non systématiquement étudiées selon FI.','Ne pas fabriquer une dose infantile à partir des comprimés adultes.']])
P.append(sec('p-4','Thiamine : prévenir sans extrapoler',thiaminetable+'''<p>Benerva existe en comprimés100et300mg et ampoules de100mg pour1ml. La thiamine est un cofacteur de réactions du métabolisme glucidique ; une réserve insuffisante peut devenir problématique au retour des apports. Le besoin quotidien physiologique, le traitement d’une carence et la prévention de renutrition d’un adulte à risque ne sont pas le même schéma [S7, S13].</p><p>La voie orale est préférée si possible ; l’injection intraveineuse doit être très lente et limitée aux patients hospitalisés en raison des réactions anaphylactoïdes. Hypersensibilité est une contre-indication. Les comprimés100mg contiennent lactose et saccharose avec contre-indications particulières d’intolérance ; les ampoules contiennent un conservateur, et la quantité restante est éliminée [S13].</p><p>Antiacides peuvent diminuer l’absorption ; des antagonistes comme5-fluorouracile interfèrent avec l’action. La FI réserve les doses de Benerva en grossesse/allaitement à une nécessité absolue, distincte des quantités couvrant les besoins quotidiens. Elle ne fournit pas un ajustement chiffré universel pour tout rein ou foie [S13].</p><p>Chez l’enfant plus jeune, l’équipe pédiatrique détermine produit, voie et dose selon le protocole applicable et les apports reçus. L’absence de dose infantile validée dans cette FI n’est pas une raison d’ignorer une carence suspectée, mais une raison de ne pas copier le tableau adulte [S3, S6, S13].</p>''','La thiamine doit être pensée avec la renutrition, mais une dose adulte ou une voie n’est pas interchangeable avec une dose infantile [S7, S13].'))
P.append(sec('p-5','Électrolytes, vitamines et risque de doublon','''<p>Phosphate, potassium et magnésium sont suivis et corrigés selon l’état, les résultats et la fonction rénale. La correction d’un seul chiffre sans rechercher les autres perturbations peut être insuffisante. Le consensus adulte souligne notamment le lien entre magnésium et hypokaliémie persistante ; ce mécanisme ne fournit pas un débit pédiatrique de perfusion [S7].</p><p>Avant supplémentation, compter ce qui provient des aliments thérapeutiques, des solutions et des médicaments. Le fait de recevoir un produit nutritionnel n’assure pas que toute anomalie soit corrigée, mais rend également possible un doublon. Les prescriptions prennent en compte voie, concentration, vitesse, quantité par prise et total quotidien [S3, S4, S7].</p><p>Les fortes doses de vitamine A ne sont pas ajoutées systématiquement à des aliments conformes déjà enrichis ; le zinc supplémentaire n’est pas routinier dans le protocole MSF lorsque les quantités recommandées d’aliments thérapeutiques sont prises. Une carence spécifique, une malabsorption ou une autre indication demandent une évaluation distincte [S3, S4, S6].</p><p>Ce cours ne donne pas de dose parentérale de phosphate, de potassium ou de magnésium sans monographie du produit exact et protocole pédiatrique adaptés. Un schéma adulte ou une dose d’essai ne devient pas une prescription générale E42. Surveillance cardiaque et biologique, fonctions d’organe et réponse clinique guident l’équipe [S6, S7].</p>''','Éviter à la fois la carence non corrigée et le doublon. Concentration, voie et vitesse comptent autant que la quantité [S3, S4, S7].'))
P.append(sec('p-6','Organiser une prescription compréhensible et réévaluable','''<p>Une prescription utile précise le produit, l’objectif, la quantité, la concentration, la voie, la fréquence et les conditions de réévaluation. Distinguer alimentation, réhydratation, traitement d’infection et supplémentation aide à repérer les doublons et les erreurs de volumes. Les prises réelles et la tolérance sont documentées [S3, S4, S7, S12, S13].</p><p>La situation change pendant les soins : œdème qui diminue, appétit qui revient, diarrhée qui persiste, fonction rénale qui se modifie ou nouvelle infection. Les besoins et les risques sont réévalués, sans appliquer indéfiniment le schéma du premier jour. Une amélioration du poids seule ne permet pas d’arrêter tous les soins [S3, S4, S7].</p><p>Lors du transfert, vérifier la capacité d’obtenir les aliments et médicaments, de les préparer, de comprendre les quantités et de revenir aux rendez-vous. Expliquer les signes de danger et les contacts à utiliser. La famille ne doit pas avoir à reconstruire un protocole en combinant des tableaux d’âges ou de sources différents [S3, S4].</p>''','La sécurité dépend d’une décision précise, appliquée et réévaluée. Un tableau exact mais incompris ne suffit pas [S3, S4, S12, S13].'))
pop('aliments','Aliments thérapeutiques : phase et quantité',foodtable+'<p>Les deux options ambulatoires de l’OMS2023 ne sont pas une réduction obligatoire après guérison. Choix du programme, tolérance, sécurité alimentaire et suivi comptent ; avant six mois, la stratégie est distincte [S3, S4].</p>')
pop('f75','F-75 : stabilisation et population','<p>F-75 contient75kcal et0,9g de protéines pour100ml. C’est un lait thérapeutique de stabilisation, pas une préparation maison à concentrer ni une prescription identique pour tout œdème. Volume, prises, eau et autres apports sont ajustés au protocole, à l’âge et à l’état. Chez le nourrisson de moins six mois avec œdème, l’OMS décrit F-75 ou formule infantile comme complément au lait maternel, avec soutien de l’allaitement [S3, S4, S6].</p>')
pop('f100','F-100 : réhabilitation et précaution avant six mois','<p>F-100 contient100kcal et2,9g de protéines pour100ml. Son rôle est différent de celui de F-75. L’OMS demande de ne pas utiliser F-100 à pleine concentration chez le nourrisson de moins de six mois instable, déshydraté, diarrhéique ou avec œdème nutritionnel, notamment à cause de la charge rénale et du risque hypernatrémique. Ce produit n’est pas interchangeable avec un lait initial au même volume [S3, S6].</p>')
pop('resomal','Réhydratation : solution, voie et limites',rehydtable+'<p>ReSoMal sous surveillance en structure, pas par famille à domicile selon OMS2023. Le choix de solution, la vitesse, la perfusion et la surveillance forment une stratégie complète ; les volumes de différents protocoles ne sont pas additionnés [S3–S5].</p>')
pop('amoxicilline','Amoxicilline : formulation suisse et protocole',amoxitable+'<p>Produit lu : suspension axapharm200mg/4ml, FI octobre2024, pas comprimé dispersible. MSF2024 et FI ont des fréquences différentes ; ne pas créer une fausse posologie composite. Rechercher allergie, diarrhée grave, réaction cutanée, interactions et fonction rénale ; agiter, conserver dix jours maximum après préparation. Sepsis ou absorption insuffisante demandent un autre parcours hospitalier [S4, S12].</p>')
pop('thiamine','Thiamine : source et âge avant la dose',thiaminetable+'<p>Benerva : FI avril2019, comprimés100/300mg et ampoule100mg/ml ; doses décrites adultes/adolescents dès12ans, usage pédiatrique non étudié systématiquement. Intraveineux très lent à l’hôpital, risque anaphylactoïde, voie orale préférée si possible. Ne pas transformer200–300mg oral ou consensus adulte en dose intraveineuse de nourrisson [S7, S13].</p>')
pop('godet','Œdème au godet et cause','<p>Un œdème prenant le godet garde une dépression après pression puis relâchement. L’examen recherche les deux pieds, la symétrie et l’extension ; l’aspect seul ne prouve pas une cause nutritionnelle. Le syndrome néphrotique peut donner un œdème déclive au godet, et une protéinurie doit être recherchée selon le contexte. Une dénutrition peut aussi coexister avec une maladie d’organe [S3, S4, S10].</p>')
pop('bras','Périmètre brachial : geste et seuil','<p>Chez l’enfant de six à cinquante-neuf mois, moins115mm indique une émaciation sévère selon l’OMS. Mesurer au milieu du bras gauche relâché, ruban au contact sans comprimer. Ce n’est ni une mesure directe de toute masse musculaire ni un seuil identique avant six mois ou chez l’adulte. Reporter la méthode et interpréter avec œdème, croissance et état hydrique [S3, S4].</p>')
pop('sortie','Transfert et fin de traitement : règles distinctes',table(['Décision','OMS2023,6–59mois','Limite'],[['Transfert hospitalier vers ambulatoire','Amélioration, absence danger24–48h, problèmes aigus suffisamment résolus, appétit et œdème non+++en diminution, suivi organisé.','Pas décision fondée seulement sur un chiffre anthropométrique.'],['Fin du traitement nutritionnel','Poids/taille ou longueur≥−2 et bras≥125mm sur deux visites/mesures, absence d’œdème sur deux visites/mesures, orientations nécessaires faites.','Pas gain pondéral absolu ou pourcentage ; recommandation conditionnelle, certitude très faible.'],['MSF2024, règle de programme','Poids/taille>−2 ou bras>125, absence œdème sur au moins deux semaines, autres soins organisés.','Divergence conservée, pas transformation de « et » en « ou » ni de deux visites en deux semaines.']])+'<p>Une récupération de poids ou la sortie de l’hôpital ne prouve pas la fin de tous les besoins de suivi [S3, S4].</p>')
pop('renutrition','Renutrition : mécanisme, population et prudence','<p>Le retour des glucides modifie les besoins et les mouvements de phosphate, potassium et magnésium, avec risque de déficit de thiamine et de rétention hydrosodée. Le consensus suisse2019 concerne des adultes médicaux et exclut les troubles alimentaires ; ses5–15kcal/kg/j initiaux et200–300mg de thiamine avant ne sont pas des doses infantiles. Défaillance clinique et anomalies biologiques demandent réévaluation, sans retarder la correction urgente d’une hypoglycémie [S6, S7, S13].</p>')
pop('profiles','Formation suisse et situations cliniques','<p>PROFILES2017 demande évaluation nutritionnelle, poids, œdème, croissance et alimentation dans l’enfance. Les compétences se travaillent par histoire, mesures, examen et décisions argumentées. Ce lien pédagogique ne constitue ni une correspondance officielle CIM–PROFILES ni une question fédérale garantie. Les chiffres de bannière hérités de la coque ne sont pas certifiés par cette leçon [S16].</p>')
pop('oms','OMS : cadre et population','<p>Organisation mondiale de la Santé. La directive2023 porte sur l’émaciation et l’œdème nutritionnel chez les moins de cinq ans, avec recommandations spécifiques pour moins de six mois et six à cinquante-neuf mois. Les critères, les certitudes et les décisions de transfert/fin de traitement gardent leur contexte ; aucune dose adulte ou stratégie universelle de renutrition ne s’en déduit [S3].</p>')
